class Solution {
public:
    int longestValidSubstring(string word, vector<string>& forbidden) {
        unordered_set<string> forbidden_set(forbidden.begin(), forbidden.end());
        int n = word.length();
        int ans = 0;
        int right_bound = n - 1;
        for (int left = n - 1; left >= 0; --left) {
            int limit = min(left + 10, right_bound + 1);
            for (int end = left; end < limit; ++end) {
                string sub = word.substr(left, end - left + 1);
                if (forbidden_set.count(sub)) {
                    right_bound = end - 1;
                    break;
                }
            }
            ans = max(ans, right_bound - left + 1);
        }
        return ans;
    }
};

import java.util.HashSet;
import java.util.List;
import java.util.Set;

class Solution {
    public int longestValidSubstring(String word, List<String> forbidden) {
        Set<String> forbiddenSet = new HashSet<>(forbidden);
        int n = word.length();
        int ans = 0;
        int rightBound = n - 1;
        for (int left = n - 1; left >= 0; left--) {
            int limit = Math.min(left + 10, rightBound + 1);
            for (int end = left; end < limit; end++) {
                String sub = word.substring(left, end + 1);
                if (forbiddenSet.contains(sub)) {
                    rightBound = end - 1;
                    break;
                }
            }
            ans = Math.max(ans, rightBound - left + 1);
        }
        return ans;
    }
}

