var longestValidSubstring = function(word, forbidden) {
    const forbiddenSet = new Set(forbidden);
    const n = word.length;
    let ans = 0;
    let rightBound = n - 1;
    for (let left = n - 1; left >= 0; left--) {
        const limit = Math.min(left + 10, rightBound + 1);
        for (let end = left; end < limit; end++) {
            const sub = word.substring(left, end + 1);
            if (forbiddenSet.has(sub)) {
                rightBound = end - 1;
                break;
            }
        }
        ans = Math.max(ans, rightBound - left + 1);
    }
    return ans;
};
